class Solution:
    def groupAnagrams(self, strs: List[str]) -> List[List[str]]:
        results = defaultdict(list)
        for s in strs:
            key = ''.join(sorted(s))
            results[key].append(s)
        return list(results.values())

class Solution:
    def groupAnagrams(self, strs: List[str]) -> List[List[str]]:
        groups = []
        for s in strs:
            placed = False
            for group in groups:
                if Counter(group[0]) == Counter(s):
                    group.append(s)
                    placed = True
                    break
            if not placed:
                groups.append([s])
        return groups
